import { Component, Input, Output, EventEmitter, OnInit, inject, ChangeDetectorRef, ChangeDetectionStrategy } from "@angular/core";
import { CommonModule } from "@angular/common";
import { Router } from "@angular/router";
import { Place } from "../../../services/api.service";
import { FirestoreFavoritesService } from "../../../services/firestore-favorites.service";

@Component({
  selector: "app-place-card",
  standalone: true,
  imports: [CommonModule],
  template: `
    <!-- Default Variant -->
    <div
      *ngIf="variant === 'default'"
      role="link"
      tabindex="0"
      (click)="navigateToPlace()"
      (keydown.enter)="navigateToPlace()"
      (keydown.space)="navigateToPlace()"
      [attr.aria-label]="place.name"
      class="block rounded-2xl border border-gray-100 overflow-hidden hover:shadow-md transition-shadow cursor-pointer focus:outline-none focus:ring-2 focus:ring-black focus:ring-offset-1 relative"
    >
      <!-- Guest login toast -->
      <div *ngIf="showLoginToast" class="absolute top-2 left-1/2 -translate-x-1/2 z-20 px-4 py-2 bg-gray-900 text-white text-xs rounded-full shadow-lg whitespace-nowrap animate-fade-in">
        🔒 Đăng nhập để lưu yêu thích
      </div>
      <div class="relative aspect-[19/6] overflow-hidden">
        <img loading="lazy"
          [src]="place.imageUrl"
          [alt]="place.name"
          class="w-full h-full object-cover"
          (error)="onImgError($event)"
        />
        <button
          type="button"
          (click)="onFavoriteClick($event)"
          [attr.aria-label]="
            isFavorite
              ? 'Bỏ yêu thích ' + place.name
              : 'Thêm vào yêu thích ' + place.name
          "
          [attr.aria-pressed]="isFavorite"
          class="absolute top-3 right-3 w-8 h-8 rounded-full bg-white/90 flex items-center justify-center shadow-sm hover:bg-white focus:outline-none focus:ring-2 focus:ring-black"
        >
          <svg
            class="w-5 h-5 transition-colors"
            [class]="isFavorite ? 'fill-red-500 text-red-500' : 'text-gray-400'"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              stroke-linecap="round"
              stroke-linejoin="round"
              stroke-width="2"
              d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
            />
          </svg>
        </button>
      </div>
      <div class="p-4">
        <div class="flex items-center gap-2 mb-2">
          <span
            class="px-2 py-0.5 rounded-full text-xs"
            [class]="place.category === 'signature' ? 'bg-gradient-to-r from-amber-400 to-orange-500 text-white shadow-sm font-medium' : 'bg-gray-100 text-gray-700'"
          >{{ getCategoryLabel(place.category) }}</span>
          <div class="flex items-center gap-1" *ngIf="place.rating">
            <svg class="w-4 h-4 fill-amber-400 text-amber-400" viewBox="0 0 20 20" aria-hidden="true">
              <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z"/>
            </svg>
            <span class="text-sm font-medium">{{ place.rating }}</span>
            <span class="text-xs text-gray-400">({{ place.reviewCount }})</span>
          </div>
        </div>
        <h3 class="text-base font-medium text-gray-900 mb-1">{{ place.name }}</h3>
        <p class="text-sm text-gray-500 line-clamp-2 mb-2">{{ place.shortDescription }}</p>
        <div class="flex flex-wrap gap-1">
          <span *ngFor="let tag of place.tags" class="text-xs text-gray-400">{{ tag }}</span>
        </div>
      </div>
    </div>

    <!-- Compact Variant -->
    <div
      *ngIf="variant === 'compact'"
      role="link"
      tabindex="0"
      (click)="navigateToPlace()"
      (keydown.enter)="navigateToPlace()"
      (keydown.space)="navigateToPlace()"
      [attr.aria-label]="place.name"
      class="flex gap-3 p-3 rounded-xl border border-gray-100 cursor-pointer hover:bg-gray-50 transition-colors focus:outline-none focus:ring-2 focus:ring-black focus:ring-offset-1"
    >
      <img loading="lazy"
        [src]="place.imageUrl"
        [alt]="place.name"
        class="w-20 h-20 rounded-lg object-cover flex-shrink-0"
        (error)="onImgError($event)"
      />
      <div class="flex-1 min-w-0">
        <h3 class="text-sm font-medium text-gray-900 mb-1 truncate">{{ place.name }}</h3>
        <p class="text-xs text-gray-500 line-clamp-2 mb-1">{{ place.shortDescription }}</p>
        <div class="flex items-center gap-1" *ngIf="place.rating">
          <svg class="w-3.5 h-3.5 fill-amber-400 text-amber-400" viewBox="0 0 20 20" aria-hidden="true">
            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z"/>
          </svg>
          <span class="text-xs">{{ place.rating }}</span>
        </div>
      </div>
      <button
        type="button"
        (click)="onFavoriteClick($event)"
        [attr.aria-label]="isFavorite ? 'Bỏ yêu thích ' + place.name : 'Thêm vào yêu thích ' + place.name"
        [attr.aria-pressed]="isFavorite"
        class="self-start w-8 h-8 rounded-full hover:bg-gray-100 flex items-center justify-center flex-shrink-0 focus:outline-none focus:ring-2 focus:ring-black"
      >
        <svg
          class="w-4 h-4 transition-colors"
          [class]="isFavorite ? 'fill-red-500 text-red-500' : 'text-gray-400'"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
          aria-hidden="true"
        >
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
            d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
          />
        </svg>
      </button>
    </div>
  `,
  styles: [`
    .line-clamp-2 {
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    @keyframes fadeIn {
      from { opacity: 0; transform: translate(-50%, -8px); }
      to { opacity: 1; transform: translate(-50%, 0); }
    }
    .animate-fade-in {
      animation: fadeIn 0.2s ease-out;
    }
  `],
})
export class PlaceCardComponent implements OnInit {
  private router = inject(Router);
  private favoritesService = inject(FirestoreFavoritesService);
  private cdr = inject(ChangeDetectorRef);

  @Input() place!: Place;
  @Input() variant: "default" | "compact" = "default";
  @Input() isFavorite = false;
  @Output() favorite = new EventEmitter<Place>();
  showLoginToast = false;

  ngOnInit() {
    // isFavorite được quản lý bởi parent qua [isFavorite] binding + onFavoriteClick
    // Không tự gọi Firestore ở đây để tránh stale state khi page bị cache
  }

  navigateToPlace() {
    this.router.navigate(["/home/place", this.place.slug]);
  }

  getCategoryLabel(category: string): string {
    const labels: Record<string, string> = {
      signature: "⭐ Đặc trưng",
      cafe: "Cafe",
      food: "Ăn uống",
      checkin: "Check-in",
      nature: "Thiên nhiên",
      homestay: "Homestay",
      rental: "🛵 Thuê xe",
    };
    return labels[category] || category;
  }

  onFavoriteClick(event: Event) {
    event.preventDefault();
    event.stopPropagation();

    // Guest user → hiện thông báo thay vì fail âm thầm
    if (!this.favoritesService.isAuthenticated()) {
      this.showLoginToast = true;
      setTimeout(() => { this.showLoginToast = false; this.cdr.markForCheck(); }, 2500);
      this.cdr.markForCheck();
      return;
    }

    const prev = this.isFavorite;
    this.isFavorite = !prev; // optimistic: đổi màu ngay
    this.favorite.emit(this.place);
    this.favoritesService.toggleFavorite({
      id: this.place.id,
      name: this.place.name,
      category: this.place.category,
      imageUrl: this.place.imageUrl,
    }).then(newState => {
      // Firestore xác nhận → cập nhật theo kết quả thực
      this.isFavorite = newState;
      this.cdr.markForCheck(); // Promise ngoài zone → trigger CD
    }).catch(() => {
      // Lỗi → rollback về trạng thái cũ
      this.isFavorite = prev;
      this.cdr.markForCheck();
    });
  }

  onImgError(event: Event) {
    const img = event.target as HTMLImageElement;
    img.onerror = null;
    img.src = this.getPlaceholder();
  }

  private getPlaceholder(): string {
    const categoryPlaceholders: Record<string, string> = {
      signature: "https://placehold.co/800x500/e2e8f0/64748b?text=Đặc+trưng",
      cafe: "https://placehold.co/800x500/e2e8f0/64748b?text=Cafe",
      food: "https://placehold.co/800x500/e2e8f0/64748b?text=Ăn+uống",
      checkin: "https://placehold.co/800x500/e2e8f0/64748b?text=Check-in",
      nature: "https://placehold.co/800x500/e2e8f0/64748b?text=Thiên+nhiên",
      homestay: "https://placehold.co/800x500/e2e8f0/64748b?text=Homestay",
      rental: "https://placehold.co/800x500/e2e8f0/64748b?text=Thuê+xe",
    };
    return categoryPlaceholders[this.place?.category] || "https://placehold.co/800x500/e2e8f0/64748b?text=Đà+Lạt";
  }
}
